      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场问候与轻互动",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天咱们聊一款很实用的包。",
              "spoken_text": "欢迎来到直播间，今天咱们聊一款很实用的包。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "姐妹平时出门，是不是总想背一个能装又不会太重的袋子？",
              "spoken_text": "姐妹平时出门，是不是总想背一个能装又不会太重的袋子？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "日常通勤和购物的选择困扰",
          "sentences": [
            {
              "display_text": "早上赶着上班，要带的东西零零碎碎，包太小塞不下，包太大又显得拖沓。",
              "spoken_text": "早上赶着上班，要带的东西零零碎碎，包太小塞不下，包太大又显得拖沓。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "下班顺路买个菜，或者周末短途出门，又希望袋子轻便一点、能随手拎着走。",
              "spoken_text": "下班顺路买个菜，或者周末短途出门，又希望袋子轻便一点、能随手拎着走。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "这种时候，一只尺寸适中、开合利落的托特包就挺省心。",
              "spoken_text": "这种时候，一只尺寸适中、开合利落的托特包就挺省心。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品名称与身份介绍",
          "sentences": [
            {
              "display_text": "今天带来的就是这款轻行可折叠通勤托特包。",
              "spoken_text": "今天带来的就是这款轻行可折叠通勤托特包。",
              "kind": "product_claim",
              "fact_ids": [
                "NAME"
              ]
            },
            {
              "display_text": "它用的是涤纶面料，包身可以折叠，尺寸是三十八乘三十乘十二厘米。",
              "spoken_text": "它用的是涤纶面料，包身可以折叠，尺寸是三十八乘三十乘十二厘米。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "主袋拉链开合与内部小口袋",
          "sentences": [
            {
              "display_text": "先看它的开合设计，主袋是拉链开合的，内部还有一个小口袋。",
              "spoken_text": "先看它的开合设计，主袋是拉链开合的，内部还有一个小口袋。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "平时坐地铁或者过安检，包里的东西不会一下子散出来，收拾起来心里有数。",
              "spoken_text": "平时坐地铁或者过安检，包里的东西不会一下子散出来，收拾起来心里有数。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "钥匙、耳机、门禁卡这些小东西放进内部小口袋，找的时候不用在包里翻半天。",
              "spoken_text": "钥匙、耳机、门禁卡这些小东西放进内部小口袋，找的时候不用在包里翻半天。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "长肩带与手提单肩两种方式",
          "sentences": [
            {
              "display_text": "它配的是长肩带，可以手提，也可以单肩背。",
              "spoken_text": "它配的是长肩带，可以手提，也可以单肩背。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "比如早上拿杯咖啡、撑个伞，手提着就走；东西多的时候往肩上一挂，两只手也能腾出来。",
              "spoken_text": "比如早上拿杯咖啡、撑个伞，手提着就走；东西多的时候往肩上一挂，两只手也能腾出来。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            },
            {
              "display_text": "通勤路上换着背法，肩膀和手可以轮换着省力。",
              "spoken_text": "通勤路上换着背法，肩膀和手可以轮换着省力。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "涤纶面料与可折叠的携带打理",
          "sentences": [
            {
              "display_text": "再来说说面料和折叠这个点。",
              "spoken_text": "再来说说面料和折叠这个点。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
